def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Simple approach: find first differing position and what needs to change
    for i, (c_in, c_out) in enumerate(zip(s_in, s_out)):
        if c_in != c_out:
            # Found first difference
            # Check if we're inserting or replacing
            if len(s_in) == len(s_out):
                return (c_in, c_out, i)
            elif len(s_in) < len(s_out):
                # Insertion case
                return (s_in[i:], s_out[i:i+len(s_in[i:])], i)
            else:
                # Deletion case  
                return (s_in[i:i+len(s_out[i:])], s_out[i:], i)

    # If we get here, one string is prefix of the other
    if len(s_in) < len(s_out):
        return (s_in[-1:], s_out[-1:], len(s_in)-1)
    else:
        return (s_in[-1:], s_out[-1:], len(s_out)-1)

